return {["fb04_01"]={["dsc"]=[[出了石林，就到了昆明的官道，青石铺成，平坦宽阔。]],["enterable"]=1,["id"]=[[fb04_01]],["left"]=[[fb04_56]],["name"]=[[青石路]],["permission"]=1,["right"]=[[fb04_02]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb04_02"]={["dsc"]=[[一条青石大道，青石铺成，平坦宽阔，远远的可以看见昆明了。]],["enterable"]=1,["id"]=[[fb04_02]],["item1"]=[[cg2item1]],["item2"]=[[bf2089dj]],["left"]=[[fb04_01]],["name"]=[[青石路]],["permission"]=1,["right"]=[[fb04_03]],["rightUp"]=[[fb04_04]],["role1"]=[[pzrw]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb04_03"]={["dsc"]=[[一条江边的小路，颇为不平，两边耸立着一些怪石。]],["enterable"]=1,["fightBackground"]=[[村庄室外]],["id"]=[[fb04_03]],["item1"]=[[2019qxhdd1]],["left"]=[[fb04_02]],["name"]=[[江边小路]],["permission"]=2,["role1"]=[[fb04r03_1]],["role2"]=[[fb04r03_2]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb04_04"]={["dsc"]=[[各种形状各异的石头，有的像人，有的像树，有的又像动物，你这边看着像这样，也许换个角度又像其他的，千姿百态。把你眼睛都看花了。]],["enterable"]=1,["id"]=[[fb04_04]],["leftDown"]=[[fb04_02]],["name"]=[[石林]],["permission"]=1,["right"]=[[fb04_05]],["role1"]=[[fb04r04_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb04_06]],["visible"]=1},["fb04_05"]={["dsc"]=[[这里是石林著名的阿诗玛峰，相传很就以前，美丽的哈尼族姑娘阿诗玛在此等侯他的阿黑哥，然而阿黑却被地主老财杀害了，阿诗玛等啊等，始终没有等来心爱的情郎，终究化作了一座石峰，永远的守侯下去。]],["enterable"]=1,["fightBackground"]=[[山外]],["id"]=[[fb04_05]],["left"]=[[fb04_04]],["name"]=[[阿诗玛]],["permission"]=1,["rightUp"]=[[fb04_07]],["role1"]=[[21drnpc01a]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb04_06"]={["down"]=[[fb04_04]],["dsc"]=[[各种形状各异的石头，有的像人，有的像树，有的又像动物，北边有一座高峰，却甚是像朵莲花，名为:莲花峰。]],["enterable"]=1,["fightBackground"]=[[山外]],["id"]=[[fb04_06]],["item1"]=[[fb04item2]],["name"]=[[莲花峰]],["permission"]=2,["role1"]=[[fb04r06_1]],["role2"]=[[fb04r06_2]],["role3"]=[[21fbnpc04_14]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb04_07"]={["dsc"]=[[各种形状各异的石头，有的像人，有的像树，有的又像动物，你这边看着像这样，也许换个角度又像其他的，千姿百态。把你眼睛都看花了。]],["enterable"]=1,["id"]=[[fb04_07]],["leftDown"]=[[fb04_05]],["name"]=[[石林]],["permission"]=1,["role1"]=[[ever07_1]],["role2"]=[[2019qxcdg1a]],["role3"]=[[2019qxcdg1b]],["stepMusic"]=[[jiaobu]],["up"]=[[fb04_08]],["visible"]=1},["fb04_08"]={["down"]=[[fb04_07]],["dsc"]=[[一条小路，颇为不平，两边耸立着一些怪石，奇形怪状，甚是有趣，北去则进入可怕的原始森林。]],["enterable"]=1,["fightBackground"]=[[村庄室外]],["id"]=[[fb04_08]],["item1"]=[[21xcdfwp]],["item2"]=[[2020qmjs1]],["name"]=[[小路]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb04_10]],["visible"]=1},["fb04_09"]={["dsc"]=[[这里是原始森林，只见迷迷茫茫全是参天大树，遮天闭日，四周光线很暗，分不清东南西北，任是谁进来都别想再出去了。上面有个山洞，是否要进去看看呢。]],["enterable"]=1,["fightBackground"]=[[森林内]],["id"]=[[fb04_09]],["name"]=[[原始森林]],["permission"]=1,["right"]=[[fb04_10]],["stepMusic"]=[[caishuye]],["up"]=[[fb04_22]],["visible"]=1},["fb04_10"]={["down"]=[[fb04_08]],["dsc"]=[[走进原始森林，只见迷迷茫茫全是参天大树，遮天闭日，四周光线很暗，分不清东南西北，任是谁进来都别想再出去了。幸好当年诸葛亮入滇时曾开出了一条路。这里向南就走出森林了，西边则传来阵阵流水。]],["enterable"]=1,["fightBackground"]=[[森林内]],["id"]=[[fb04_10]],["left"]=[[fb04_09]],["name"]=[[原始森林]],["permission"]=1,["right"]=[[fb04_67]],["rightUp"]=[[fb04_11]],["stepMusic"]=[[caishuye]],["visible"]=1},["fb04_11"]={["dsc"]=[[走进原始森林，只见迷迷茫茫全是参天大树，遮天闭日，四周光线很暗，分不清东南西北，任是谁进来都别想再出去了。幸好当年诸葛亮入滇时曾开出了一条路。否则，你不被猛兽吃了，也要被毒瘴毒死，所以还是快离开这里！]],["enterable"]=1,["fightBackground"]=[[森林内]],["id"]=[[fb04_11]],["item1"]=[[csjlldj]],["leftDown"]=[[fb04_10]],["name"]=[[原始森林]],["permission"]=1,["right"]=[[fb04_12]],["stepMusic"]=[[caishuye]],["up"]=[[fb04_63]],["visible"]=1},["fb04_12"]={["dsc"]=[[来到这里，只听得流水声越来越大，你感觉到一阵阵雾气向你袭来，树木渐渐稀少，花草却多了起来，西北方向穿过花丛似乎有条小路能走过去。]],["enterable"]=1,["fightBackground"]=[[森林内]],["id"]=[[fb04_12]],["left"]=[[fb04_11]],["name"]=[[原始森林]],["permission"]=1,["stepMusic"]=[[caishuye]],["up"]=[[fb04_13]],["visible"]=1},["fb04_13"]={["BgmDown"]=1,["down"]=[[fb04_12]],["dsc"]=[[进入云贵高原，泥土变为了红色，空气变得更清新，放眼看去，只见绵绵原始森林不见边际，你顿时觉得心高志远，一股豪情涌了上来，想要做一方大事业。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb04_13]],["name"]=[[红土路]],["permission"]=1,["rightUp"]=[[fb04_14]],["role1"]=[[fb04r13_1a]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb04_14"]={["BgmDown"]=1,["dsc"]=[[进入云贵高原，泥土变为了红色，空气变得更清新，放眼看去，只见绵绵原始森林不见边际，你顿时觉得心高志远，一股豪情涌了上来，想要做一方大事业。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb04_14]],["leftDown"]=[[fb04_13]],["name"]=[[红土路]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb04_15]],["visible"]=1},["fb04_15"]={["BgmDown"]=1,["down"]=[[fb04_14]],["dsc"]=[[你走在一条崎岖的山路上，再往南，就进入了云贵高原了。北面是一条大河拦住去路。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb04_15]],["name"]=[[山路]],["permission"]=1,["role1"]=[[fb04r15_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb04_16]],["visible"]=1},["fb04_16"]={["BgmDown"]=1,["down"]=[[fb04_15]],["dsc"]=[[你来到了长江南岸，只见波涛滚滚，滔滔江水向东流去。岸边立有一块碑，前面不远处有座独木桥。]],["enterable"]=1,["id"]=[[fb04_16]],["name"]=[[长江南岸]],["permission"]=1,["role1"]=[[bfitem1]],["role2"]=[[2021fhddd1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb04_17]],["visible"]=1},["fb04_17"]={["BgmDown"]=1,["down"]=[[fb04_16]],["dsc"]=[[一座独木桥，也不知是什么时候架起来的，走在上面摇摇晃晃，很是危险，当然要过河的话，只有走这里。从桥上望下去，只见急流勇潺，一掉下去，肯定没命。]],["enterable"]=1,["id"]=[[fb04_17]],["item1"]=[[fb04item11]],["name"]=[[独木桥]],["permission"]=1,["role1"]=[[fb04r17_1]],["stepMusic"]=[[mudiban]],["up"]=[[fb04_18]],["visible"]=1},["fb04_18"]={["BgmDown"]=1,["down"]=[[fb04_17]],["dsc"]=[[你来到了长江北岸，只见波涛滚滚，滔滔江水向东流去。岸边立有一块碑，前面不远处有座独木桥。]],["enterable"]=1,["id"]=[[fb04_18]],["name"]=[[长江北岸]],["permission"]=1,["role1"]=[[fb04r18_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb04_19]],["visible"]=1},["fb04_19"]={["BgmDown"]=1,["down"]=[[fb04_18]],["dsc"]=[[这里怪石林立，路极不好走，不小心就要摔个跟斗，过了这片石滩，就是长江岸边。]],["enterable"]=1,["fightBackground"]=[[山外]],["id"]=[[fb04_19]],["item1"]=[[fb04item12]],["name"]=[[乱石滩]],["permission"]=2,["rightUp"]=[[fb04_21]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb04_20"]={["BgmDown"]=1,["dsc"]=[[这里怪石林立，路极不好走，不小心就要摔个跟斗，过了这片石滩，就是长江岸边。]],["enterable"]=1,["fightBackground"]=[[山外]],["id"]=[[fb04_20]],["name"]=[[乱石滩]],["permission"]=2,["role1"]=[[fb04r20_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb04_21]],["visible"]=1},["fb04_21"]={["BgmDown"]=1,["down"]=[[fb04_20]],["dsc"]=[[这里怪石林立，路极不好走，不小心就要摔个跟斗，过了这片石滩，就是长江岸边。]],["enterable"]=1,["fightBackground"]=[[山外]],["id"]