pMusic"]=[[jiaobu]],["up"]=[[fb04_64]],["visible"]=1},["fb04_64"]={["down"]=[[fb04_63]],["dsc"]=[[隐有人开辟过的痕迹，半人高的灌木被压分出两边，且行走时可见地上淡黄色的药粉，走到尽头颇有柳暗花明之感。]],["enterable"]=1,["id"]=[[fb04_64]],["name"]=[[小路]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb04_65]],["visible"]=1},["fb04_65"]={["down"]=[[fb04_64]],["dsc"]=[[“田”本四方，此处的农田却开辟的甚是奇特，东南西北各一块，形状不一，中间留有一颗粗树，一旁斜放着一个锄头，看这田中所种的豆苗零零散散，似锄头到哪便在那撒种，反倒杂草生的颇为有序。]],["enterable"]=1,["id"]=[[fb04_65]],["name"]=[[农田]],["permission"]=2,["role1"]=[[csjyynpc]],["stepMusic"]=[[jiaobu]],["up"]=[[fb04_66]],["visible"]=1},["fb04_66"]={["down"]=[[fb04_65]],["dsc"]=[[一间简陋的小屋，屋前的篱笆已被林中的灌木爬满，两个水桶里装满了水，扁担倒在一旁，若是上前轻叩柴门，竟能将屋顶上歇落的鸟群全部惊飞。]],["enterable"]=1,["id"]=[[fb04_66]],["item1"]=[[csjzhlt]],["name"]=[[小屋]],["permission"]=2,["stepMusic"]=[[jiaobu]],["visible"]=1},["fb04_67"]={["dsc"]=[[这里是原始森林，只见东南西北全是参天大树，遮天闭日，四周光线很暗，分不清方向，任是谁进来都别想再出去了。]],["enterable"]=1,["id"]=[[fb04_67]],["item1"]=[[znq3zgsxhd5]],["left"]=[[fb04_10]],["name"]=[[原始森林]],["permission"]=2,["right"]=[[fb04_68]],["role1"]=[[znq3xsnpc1]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb04_68"]={["down"]=[[fb04_69]],["dsc"]=[[一条刚刚开辟出的小路，颇为不平，两边耸立着一些怪石，奇形怪状，甚是有趣。]],["enterable"]=1,["id"]=[[fb04_68]],["left"]=[[fb04_67]],["name"]=[[小路]],["permission"]=2,["role1"]=[[znq3xsnpc2]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb04_69"]={["down"]=[[fb04_70]],["dsc"]=[[一条刚刚开辟出的小路，颇为不平，两边耸立着一些怪石，奇形怪状，甚是有趣。]],["enterable"]=1,["id"]=[[fb04_69]],["item1"]=[[znq3zgsxmm]],["name"]=[[小路]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb04_68]],["visible"]=1},["fb04_70"]={["dsc"]=[[新建的茅草屋，看上去有些破烂，经不起大风大雨。屋前架着一个火堆，似乎有人在此居住。周围幽寂，隐隐能听到野兽的吼声。]],["enterable"]=1,["id"]=[[fb04_70]],["item1"]=[[znq3zgpd]],["name"]=[[茅草屋]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb04_69]],["visible"]=1}}0000000